  lv_label_set_long_mode        (artist_label, LV_LABEL_LONG_DOT);
  lv_obj_set_grid_cell          (artist_label, LV_GRID_ALIGN_START, 1, 1, LV_GRID_ALIGN_CENTER, 1, 1);
