  lv_obj_add_style              (heart, &style_heart,         (uint32_t)LV_PART_INDICATOR | (uint32_t)LV_STATE_DEFAULT);
  lv_obj_add_style              (heart, &style_heart,         (uint32_t)LV_PART_INDICATOR | (uint32_t)LV_STATE_CHECKED);
